const fs = require('fs');

function t(zh, sr, en) { return { zh, sr, en }; }
function w(zh, py, sr) { return { zh, py, sr }; }
function choice(zhPrompt, srPrompt, enPrompt, options, correct) {
  return { type: 'choice', prompt: { zh: zhPrompt, sr: srPrompt, en: enPrompt }, options, correct };
}

